import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import type { PrimitiveProps } from "../primitives";

const BASE = "#000000";
const GLOW = "255, 255, 255";

const DynamicBlack: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const t = frame / fps;
  const TAU = Math.PI * 2;

  // Seamless periodic phases (seconds per cycle)
  const a = (t / 23) * TAU;
  const b = (t / 31) * TAU;
  const c = (t / 41) * TAU;

  // Eased breathing pulse on a repeating 12s phase
  const phase = (t % 12) / 12;
  const breath = interpolate(phase, [0, 0.5, 1], [0, 1, 0], {
    easing: Easing.inOut(Easing.sin),
  });

  const blobs = [
    { x: 30 + 18 * Math.sin(a), y: 25 + 12 * Math.cos(b), r: 900, o: 0.07 + 0.03 * breath },
    { x: 72 + 15 * Math.cos(b), y: 62 + 14 * Math.sin(c), r: 1000, o: 0.06 + 0.02 * Math.sin(a) },
    { x: 45 + 20 * Math.sin(c), y: 88 + 8 * Math.cos(a), r: 800, o: 0.05 + 0.02 * Math.cos(b) },
  ];

  // Slow diagonal light sweep that loops every 41s
  const sweepX = 50 + 60 * Math.sin(c);

  return (
    <AbsoluteFill style={{ backgroundColor: BASE, overflow: "hidden" }}>
      {blobs.map((bl, i) => (
        <AbsoluteFill
          key={i}
          style={{
            background: `radial-gradient(${bl.r}px circle at ${bl.x}% ${bl.y}%, rgba(${GLOW}, ${bl.o}) 0%, rgba(${GLOW}, 0) 70%)`,
          }}
        />
      ))}
      <AbsoluteFill
        style={{
          background: `linear-gradient(115deg, rgba(${GLOW}, 0) ${sweepX - 25}%, rgba(${GLOW}, 0.025) ${sweepX}%, rgba(${GLOW}, 0) ${sweepX + 25}%)`,
        }}
      />
      <AbsoluteFill
        style={{
          background: "radial-gradient(ellipse at 50% 50%, rgba(0,0,0,0) 45%, rgba(0,0,0,0.75) 100%)",
        }}
      />
    </AbsoluteFill>
  );
};

export default DynamicBlack;
